'use client';
import { useCollection, useFirestore, useMemoFirebase, useUser } from '@/firebase';
import { collection, query, where, orderBy } from 'firebase/firestore';
import { VirtualAccount } from '@/lib/data';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Skeleton } from '@/components/ui/skeleton';
import { Copy } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useToast } from '@/hooks/use-toast';
import { useMemo } from 'react';

function AccountItem({ account }: { account: VirtualAccount }) {
    const { toast } = useToast();

    const handleCopy = (text: string, label: string) => {
        navigator.clipboard.writeText(text);
        toast({
            title: `${label} Copied!`,
            description: text,
        })
    }

  return (
    <div className="rounded-lg border bg-background p-4 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
      <div>
        <p className="font-semibold text-lg">{account.accountName}</p>
        <p className="text-muted-foreground">{account.bankName}</p>
      </div>
      <div className="text-left sm:text-right">
        <div className="flex items-center gap-2">
            <p className="font-mono text-lg">{account.accountNumber}</p>
            <Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => handleCopy(account.accountNumber, "Account Number")}>
                <Copy className="h-4 w-4" />
            </Button>
        </div>
        <p className="font-bold text-xl">
          {new Intl.NumberFormat('en-NG', {
            style: 'currency',
            currency: account.currency,
          }).format(account.balance)}
        </p>
      </div>
    </div>
  );
}

function AccountListSkeleton() {
  return (
    <div className="space-y-4">
      <div className="h-24 w-full rounded-lg border p-4 flex items-center justify-between">
        <div className="space-y-2">
          <Skeleton className="h-5 w-48" />
          <Skeleton className="h-4 w-32" />
        </div>
        <div className="space-y-2 text-right">
          <Skeleton className="h-5 w-36 ml-auto" />
          <Skeleton className="h-6 w-28 ml-auto" />
        </div>
      </div>
       <div className="h-24 w-full rounded-lg border p-4 flex items-center justify-between">
        <div className="space-y-2">
          <Skeleton className="h-5 w-40" />
          <Skeleton className="h-4 w-32" />
        </div>
        <div className="space-y-2 text-right">
          <Skeleton className="h-5 w-36 ml-auto" />
          <Skeleton className="h-6 w-32 ml-auto" />
        </div>
      </div>
    </div>
  );
}

export default function AccountList() {
  const firestore = useFirestore();
  const { user } = useUser();

  const accountsQuery = useMemoFirebase(
    () =>
      firestore && user
        ? query(
            collection(firestore, 'virtual_accounts'),
            where('userId', '==', user.uid)
          )
        : null,
    [firestore, user]
  );

  const {
    data,
    isLoading,
    error,
  } = useCollection<VirtualAccount>(accountsQuery);

  const accounts = useMemo(() => {
    if (!data) return [];
    // Sort on the client-side
    return [...data].sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  }, [data]);

  return (
    <Card>
      <CardHeader>
        <CardTitle>Your Virtual Accounts</CardTitle>
        <CardDescription>
          Use these accounts to receive payments from anyone.
        </CardDescription>
      </CardHeader>
      <CardContent>
        <div className="space-y-4">
          {isLoading && <AccountListSkeleton />}
          {!isLoading && error && (
            <p className="text-center text-destructive">
              Could not load your accounts.
            </p>
          )}
          {!isLoading && accounts && accounts.length > 0 && (
            accounts.map((acc) => <AccountItem key={acc.id} account={acc} />)
          )}
          {!isLoading && accounts?.length === 0 && (
             <div className="flex items-center justify-center text-center h-40 rounded-lg border border-dashed">
                <p className="text-muted-foreground">You don't have any virtual accounts yet. <br/> Create one to get started.</p>
             </div>
          )}
        </div>
      </CardContent>
    </Card>
  );
}
